import{_ as t,o,c as d,a3 as s}from"./chunks/framework.D1GAkLkK.js";const u=JSON.parse('{"title":"Expressions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/expressions.md","filePath":"reference/expressions.md"}'),a={name:"reference/expressions.md"};function c(i,e,n,r,h,l){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="expressions" tabindex="-1">Expressions <a class="header-anchor" href="#expressions" aria-label="Permalink to &quot;Expressions&quot;">​</a></h1><p>A value in <code>${{ }}</code> is an expression in <a href="https://cel.dev" target="_blank" rel="noreferrer">CEL</a>, the Common Expression Language. It reads inputs, the outputs of units, tasks, and steps, secrets, and facts of the run.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">units</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cat.compose</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      IMAGE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">${{ units.build.outputs.image }}</span></span></code></pre></div><h2 id="what-an-expression-reads" tabindex="-1">What an expression reads <a class="header-anchor" href="#what-an-expression-reads" aria-label="Permalink to &quot;What an expression reads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>What it is</th></tr></thead><tbody><tr><td><code>inputs.&lt;name&gt;</code></td><td>An input of the task, the component, or the project, through its stack</td></tr><tr><td><code>locals.&lt;name&gt;</code></td><td>A local of the project or the component</td></tr><tr><td><code>units.&lt;name&gt;.outputs.&lt;key&gt;</code></td><td>A stored output of a unit</td></tr><tr><td><code>units.&lt;name&gt;[&#39;&lt;key&gt;&#39;].outputs.&lt;k&gt;</code></td><td>One instance of a unit with <code>for_each</code></td></tr><tr><td><code>units[&#39;my-db&#39;].outputs.&lt;key&gt;</code></td><td>A unit whose name has a <code>-</code></td></tr><tr><td><code>units.&lt;name&gt;.changed</code>, <code>.outcome</code>, <code>.plan</code></td><td>Whether the unit changed something in this run, how it ended (<code>success</code>, <code>failure</code>, <code>skipped</code>, <code>cancelled</code>), and its last plan: <code>changes</code>, <code>outputs</code>, <code>exact</code>, <code>digest</code>, <code>summary</code></td></tr><tr><td><code>tasks.&lt;name&gt;.outputs.&lt;key&gt;</code></td><td>An output of a task in the same run</td></tr><tr><td><code>steps.&lt;id&gt;.outputs.&lt;key&gt;</code></td><td>An output of a step of the same task</td></tr><tr><td><code>steps.&lt;id&gt;.changed</code>, <code>.outcome</code></td><td>Whether the step changed something, and how it ended</td></tr><tr><td><code>steps.&lt;id&gt;.units[&#39;&lt;address&gt;&#39;]</code></td><td>What a <code>task: up</code> step, or another task of units, did to each instance</td></tr><tr><td><code>secrets.&lt;name&gt;</code></td><td>A secret, hidden in what OpsTruss writes</td></tr><tr><td><code>stack</code></td><td>The name of the stack</td></tr><tr><td><code>each.key</code>, <code>each.value</code></td><td>The item of <code>for_each</code></td></tr><tr><td><code>event.&lt;field&gt;</code></td><td>The event of a trigger; <code>event.time</code> and <code>event.trigger</code> are in every run</td></tr><tr><td><code>outputs</code></td><td>In <code>retry.until</code>, <code>failed_when</code>, and <code>changed_when</code>: the outputs being judged</td></tr><tr><td><code>opstruss.project</code></td><td>The <code>name</code> of the root project, also inside a component</td></tr><tr><td><code>opstruss.address</code>, <code>opstruss.dir</code></td><td>The address of the unit, and the directory of the file that writes it</td></tr><tr><td><code>opstruss.os</code>, <code>.arch</code>, <code>.host</code>, <code>.time</code>, <code>.run</code></td><td>Facts of the machine and the run; <code>time</code> is when the run started</td></tr><tr><td><code>opstruss.cwd</code></td><td>Where OpsTruss started, before <code>-C</code>; in tasks and steps only</td></tr><tr><td><code>opstruss.artifacts</code>, <code>opstruss.temp</code></td><td><code>$OPSTRUSS_ARTIFACTS</code> and <code>$OPSTRUSS_TEMP</code> of the run; in tasks and steps only</td></tr><tr><td><code>opstruss.state_key</code>, <code>opstruss.reason</code></td><td>In a task that a unit uses: <code>$OPSTRUSS_STATE_KEY</code> and <code>$OPSTRUSS_REASON</code></td></tr></tbody></table><p>There is no <code>env</code> namespace: a value from the environment comes in as an input with <code>env:</code>, or a secret with <code>env:</code>.</p><p>A unit, task, or step with <code>for_each</code> is a map from key to the result of each instance. A macro combines them, such as <code>steps.attempts.exists(k, v, v.outcome == &#39;success&#39;)</code>.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><p>OpsTruss adds:</p><table tabindex="0"><thead><tr><th>Function</th><th>What it gives</th></tr></thead><tbody><tr><td><code>file(&#39;&lt;path&gt;&#39;)</code></td><td>The text of a file, relative to the file that writes the expression; at most 1 MiB</td></tr><tr><td><code>kv(&#39;&lt;key&gt;&#39;)</code>, <code>kv(&#39;&lt;key&gt;&#39;, &lt;default&gt;)</code></td><td>A value of the <a href="./builtin-tasks#kv">memory of the stack</a>, or <code>null</code> or the default; <code>kv(&#39;&lt;prefix&gt;*&#39;)</code> gives every key with the prefix as a map</td></tr><tr><td><code>toJSON()</code>, <code>fromJSON()</code>, <code>toYAML()</code>, <code>fromYAML()</code></td><td>Data as text, and text as data</td></tr><tr><td><code>sha256()</code></td><td>The SHA-256 of a string, in hex</td></tr><tr><td><code>&lt;timestamp&gt;.strftime(&#39;&lt;format&gt;&#39;, &#39;&lt;timezone&gt;&#39;)</code></td><td>A time as <code>strftime</code> writes it, in UTC without a time zone</td></tr></tbody></table><p>Yesterday in Jakarta: <code>(opstruss.time - duration(&#39;24h&#39;)).strftime(&#39;%Y-%m-%d&#39;, &#39;Asia/Jakarta&#39;)</code>.</p><p>Standard CEL has <code>size</code>, <code>contains</code>, <code>startsWith</code>, <code>endsWith</code>, <code>matches</code>, <code>int</code>, <code>string</code>, <code>has</code>, <code>map</code>, <code>filter</code>, <code>all</code>, <code>exists</code>, <code>timestamp()</code>, <code>duration()</code>, and the getters of time. The official extensions of cel-go are there too: strings (<code>join</code>, <code>split</code>, <code>trim</code>, <code>replace</code>, <code>format</code>, …), lists (<code>lists.range</code>, <code>slice</code>, <code>flatten</code>, <code>distinct</code>, <code>sort</code>, …), math, sets, two-variable comprehensions (<code>transformList</code>, <code>transformMap</code>, …), optional values (<code>?.</code>, <code>orValue</code>), <code>cel.bind</code>, and <code>base64</code>.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><ul><li>A value that is a single <code>${{ }}</code> keeps the type of its result: a list, a map, a number, or a boolean, also in quotes in YAML.</li><li><code>${{ }}</code> inside text gives a string. Numbers and booleans become text; a list, a map, or <code>null</code> is refused, with <code>toJSON()</code> as the way to write it.</li><li>A value of <code>env:</code> and an item of a <code>run</code> list are always strings.</li><li>A number takes the type of the input or output it goes to: a <code>number</code> is a <code>double</code>, also when it is whole, and an <code>integer</code> is an <code>int</code>, which holds 64 bits, so an id larger than that is a string. Without a type, as from <code>fromJSON()</code>, a whole number becomes an <code>int</code> and any other a <code>double</code>, so <code>80</code> and <code>80.0</code> from two tools are equal. An expression does not mix the two, as in <code>2 / 4.0</code>; write <code>double(x)</code> for a value without a type.</li><li>A map is always read in the order of its keys, in macros, in <code>for_each</code>, and as a list, so the same result gives the same digest.</li><li>The result of an expression that reads a secret or a sensitive value is sensitive too: it is hidden in logs, records, and events. A map or list written in YAML keeps that mark per key and per item, so only <code>token: ${{ secrets.api }}</code> is sensitive in a <code>with</code> that also has <code>url</code>.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>A condition, as <code>if</code>, <code>failed_when</code>, <code>changed_when</code>, <code>retry.until</code>, and <code>that</code> of <code>assert</code>, may be written without <code>${{ }}</code>, unless it starts with <code>!</code>.</li><li><code>$${{</code> writes <code>${{</code> as it is, as when a task writes a workflow of GitHub Actions.</li><li>An expression ends at the first <code>}}</code> outside quotes and braces, so a map such as <code>${{ {&#39;a&#39;: {&#39;b&#39;: 1}} }}</code> stays whole.</li><li><code>${{ }}</code> is refused in a script of <code>run</code>, <code>service</code>, and <code>destroy</code>, and in a <code>literal</code> input such as <code>command.script</code>: a value goes in through <code>env:</code> and the script reads <code>$NAME</code>.</li><li><code>opstruss.cwd</code>, <code>opstruss.artifacts</code>, and <code>opstruss.temp</code> are refused in units, since what a unit is does not depend on where a command was typed or on one run.</li><li><code>validate</code> checks what follows <code>steps.&lt;id&gt;</code>, and the outputs that are known before the run, and an error names what to write instead: a name close to the one written, <code>units[&#39;my-db&#39;]</code> for a name with <code>-</code>, or an input for <code>$NAME</code>, since an expression does not read the environment.</li></ul>',16)])])}const m=t(a,[["render",c]]);export{u as __pageData,m as default};
